example:
composition "Region merge" { ample 1  tempo 96  master-seed 79 }

midi-clip phrase {
  chords C Am F G
  bars 4
}

synth source {
  wave triangle
  gain -9 dB
  from phrase.notes -> notes
}

cut opening {
  first 2s
  from source.audio -> audio
}

region-merge merged {
  from opening.region -> region
}

master output {
  from merged.audio -> audio
}
